ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{	
	message: "All products deleted successfully"
}

%dw 2.0
output application/json
---
payload.items map ((item, index) ->{
    ("Product"++(index+1)):if(item.exception == null)"Product deteted successfully" else if(item.exception.message contains "ENTITY_IS_DELETED")"Product already deleted" else item.exception.message  
} )

%dw 2.0
output application/json
---
{	
	message: "All product updated successfully"
}

%dw 2.0
output application/json
---
payload.items map ((item, index) ->{
    ("Product"++(index+1)):if(item.exception == null)"Product updated successfully" else item.exception.message  
} )
